import clsx from 'clsx';
import React, {
  FocusEvent,
  forwardRef,
  PropsWithChildren,
  Ref,
  RefObject,
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useReducer,
  useRef,
  useState,
} from 'react';
import ReactSelect, { createFilter, GroupBase } from 'react-select';

import { components } from './components/components.js';
import { SelectMenuContext } from './contexts/SelectMenuContext.js';
import { useSelectV2Options } from './hooks/use-select-options.js';
import { useSelectV2Slots } from './hooks/use-select-slots.js';
import { useSelectV2Value } from './hooks/use-select-value.js';
import { SelectV2Content } from './SelectContent.js';
import { SelectV2CustomTrigger } from './SelectCustomTrigger.js';
import { SelectV2DisplayValue } from './SelectDisplayValue.js';
import { SelectV2EmptyState } from './SelectEmptyState.js';
import { SelectV2Filter, SelectV2FilterProps } from './SelectFilter.js';
import { SelectV2Group, SelectV2GroupLabel } from './SelectGroup.js';
import { SelectV2Option } from './SelectOption.js';
import { SelectV2Prefix } from './SelectPrefix.js';
import { SelectV2Suffix } from './SelectSuffix.js';
import { SelectV2Trigger } from './SelectTrigger.js';
import {
  reducer,
  SelectActions,
  type SelectReducerAction,
} from './state/select-menu-state-reducer.js';
import { selectWrapperCSS, validAndEnabledCSS } from './styles/Select.sty.js';
import type {
  _BaseOption,
  SelectContentWidthOptionsType,
  SelectTriggerWidthOptionsType,
  SelectV2MultiValue,
  SelectV2SingleValue,
} from './types.js';
import { _useAriaLabelingProps } from '../../core/hooks/useAriaLabelingProps.js';
import { _useControllableState } from '../../core/hooks/useControllableState.js';
import { _useFormControlState } from '../../core/hooks/useFormControlState.js';
import { _useId } from '../../core/hooks/useId.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { DOMProps } from '../../core/types/dom.js';
import type {
  FormControlState,
  FormControlStateProps,
} from '../../core/types/form-control-state.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { _useFormFieldContext } from '../forms-core/hooks/useFormFieldContext.js';
import { FormFieldAction } from '../forms-core/state/formfield-state-reducer.js';
import type {
  FormControlRef,
  FormControlWithOverlayRef,
} from '../shared-types.js';

// Redeclare react-select module to extend it with additional props for typesafety.
// https://react-select.com/typescript#custom-select-props
declare module 'react-select/dist/declarations/src/Select' {
  export interface Props<
    Option,
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    IsMulti extends boolean,
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    Group extends GroupBase<Option>,
  > {
    /** Custom placeholder text */
    placeholderText?: React.ReactNode;
    /** The trigger width set by the dev. */
    triggerWidth?: SelectTriggerWidthOptionsType;
    /** Custom select trigger */
    customTrigger?: React.ReactElement;
    /** Custom display value. */
    displayValue?: React.ReactNode[];
    /** Prefix for the select trigger */
    prefix?: React.ReactElement;
    /* TriggerRef that needs to be applied to the trigger in order to setup the menu positioning */
    triggerRef: HTMLElement | null;
    /* setter for the TriggerRef */
    setTriggerRef: React.Dispatch<React.SetStateAction<HTMLDivElement | null>>;
    /** Defines if the space for the prefix icons should be reserved in all options rendered */
    optionsHavePrefix: boolean;
    /** Select.Filter component specified by dev */
    customFilter?: React.ReactElement<SelectV2FilterProps>;
    /** Custom empty state provided by dev */
    emptyState?: React.ReactElement;
    /** Form control state for errors and hints */
    controlState?: FormControlState;
    loading?: boolean;
    clearable?: boolean;
    isRequired?: boolean;
    /** array of all select options (including those in groups) */
    allOptions?: _BaseOption<Option>[];
    hiddenSelectRef: Ref<HTMLSelectElement>;
    hiddenSelectName?: string;
    /** whether the focus styles on the options should be visible */
    focusOnOption: boolean;
    /** Ref that needs to be applied to the filter input to manage the focus and keyboard navigation */
    filterRef?: RefObject<FormControlRef<HTMLDivElement>>;
    /** Ref that needs to be applied to the clear selection element to manage the focus and keyboard navigation */
    clearSelectionRef?: RefObject<HTMLElement>;
    /** The content width set by the dev. */
    contentWidth?: SelectContentWidthOptionsType;
    /** Whether the selected options are reordered to the top of the options. */
    showSelectedOptionsFirst?: boolean;
    /** The id used for the hidden input. */
    selectInputId?: string;
    /** All aria-labeling props. */
    ariaLabelingProps?: AriaLabelingProps;
    /** className and style prop for each of the components. */
    componentProps: {
      trigger?: StylingProps & DataTestId;
      content?: StylingProps & DataTestId;
      filter?: StylingProps & DataTestId;
      emptyState?: StylingProps & DataTestId;
    };
  }
}

// Redeclare react forwardRef to allow generic types on react
// https://fettblog.eu/typescript-react-generic-forward-refs/#option-3%3A-augment-forwardref
declare module 'react' {
  function forwardRef<T, P = unknown>(
    render: (props: P, ref: React.Ref<T>) => React.ReactElement | null,
  ): (props: P & React.RefAttributes<T>) => React.ReactElement | null;
}

/**
 * Common select base props.
 * @internal
 */
export type _SelectV2BaseProps<
  T,
  Multiple extends boolean,
> = PropsWithChildren<{
  /**
   * Used to compare options with objects for values either by a specified property of the object or through a comparator function.
   */
  compareBy?: keyof T | ((valueA: T, valueB: T) => boolean);

  /** Name used for the component when submitting it in a form */
  name?: string;

  /** Form name used to connect the component to a form */
  form?: string;

  /**
   * Boolean to determine whether the component is required
   *
   * @defaultValue false
   */
  required?: boolean;

  /**
   * Whether the component is disabled
   *
   * @defaultValue false
   */
  disabled?: boolean;

  /**
   * Event handler called when the open state for the select changes
   */
  onOpenChange?: (isOpen: boolean) => void;

  /**
   * Whether or not the select allows multiple selection or not
   * @defaultValue false
   */
  multiple?: Multiple;

  /**
   * Whether or not the select is clearable.
   * @defaultValue false for single select, true for multi select
   */
  clearable?: boolean;

  /** Callback that is called when the select trigger loses focus. */
  onBlur?: (e: FocusEvent<HTMLInputElement, Element>) => void;

  /** Callback that is called when the select trigger gets focus. */
  onFocus?: (e: FocusEvent<HTMLInputElement, Element>) => void;
}>;

export type SelectV2OnChangeValue<
  OptionValue,
  Multiple extends boolean,
> = Multiple extends true
  ? SelectV2MultiValue<OptionValue>
  : SelectV2SingleValue<OptionValue>;

export interface SelectValueControlledProps<
  OptionValue,
  Multiple extends boolean,
> {
  value: Multiple extends true
    ? SelectV2MultiValue<OptionValue>
    : SelectV2SingleValue<OptionValue>;

  onChange: (value: SelectV2OnChangeValue<OptionValue, Multiple>) => void;

  defaultValue?: never;
}

export interface SelectValueUncontrolledProps<
  OptionValue,
  Multiple extends boolean,
> {
  value?: never;

  onChange?: (value: SelectV2OnChangeValue<OptionValue, Multiple>) => void;

  defaultValue?: Multiple extends true
    ? SelectV2MultiValue<OptionValue>
    : SelectV2SingleValue<OptionValue>;
}

/** Accepted properties for Select */

export type SelectV2Props<
  /*
   * TODO: Figure out how we can properly infer the type of the Select here
   * because that would come from the value of the options (as children)
   * which is not really doable with the given API.
   */
  OptionValue,
  Multiple extends boolean,
> = _SelectV2BaseProps<OptionValue, Multiple> &
  (
    | SelectValueControlledProps<OptionValue, Multiple>
    | SelectValueUncontrolledProps<OptionValue, Multiple>
  ) &
  FormControlStateProps &
  DOMProps &
  StylingProps &
  DataTestId;

/** Select component */
function _SelectV2<OptionValue, Multiple extends boolean = false>(
  props: SelectV2Props<OptionValue, Multiple>,
  forwardedRef: React.Ref<FormControlWithOverlayRef>,
) {
  const {
    multiple = false,
    disabled: propDisabled,
    controlState,
    clearable = multiple,
    name,
    id: propId,
    onFocus,
    onBlur,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId = 'selectv2',
    onOpenChange,
    required: propRequired,
    ...remainingProps
  } = props;

  const slots = useSelectV2Slots(props.children);

  const {
    optionsOrGroups: options,
    optionsHavePrefix,
    allOptions,
  } = useSelectV2Options<OptionValue>(slots.Content);

  const { value, defaultValue } = useSelectV2Value<OptionValue, Multiple>({
    value: props.value,
    defaultValue: props.defaultValue,
    options,
    multiple: (multiple === true) as Multiple,
  });

  const [triggerRef, setTriggerRef] = useState<HTMLDivElement | null>(null);

  const menuOpenReducer = useCallback(
    (state: boolean, action: SelectReducerAction) => {
      const newState = reducer(state, action);

      if (state !== newState) {
        onOpenChange?.(newState);
      }

      return newState;
    },
    [onOpenChange],
  );

  const [menuOpen, dispatch] = useReducer(menuOpenReducer, false);

  const {
    disabled: contextDisabled,
    required: contextRequired,
    controlId,
    dispatch: formFieldDispatch,
  } = _useFormFieldContext();

  const fallbackId = _useId();
  const id = propId || controlId || fallbackId;
  const disabled = propDisabled ?? contextDisabled;
  const required = propRequired ?? contextRequired;

  useEffect(
    () =>
      formFieldDispatch?.({
        type: FormFieldAction.UPDATE,
        payload: {
          id: propId,
          disabled: propDisabled,
          required: propRequired,
        },
      }),
    [formFieldDispatch, propDisabled, propId, propRequired],
  );

  const [filterValue, setFilterValue] = _useControllableState({
    value: slots.Filter?.props.value,
    defaultValue: slots.Filter?.props.defaultValue,
    onChange: slots.Filter?.props.onChange,
  });

  const hiddenSelectRef = useRef<HTMLSelectElement>(null);
  const hiddenTrigger = useMemo(
    () => triggerRef?.querySelector('input'),
    [triggerRef],
  );
  const [focusOnOption, setFocusOnOption] = useState<boolean>(true);

  const ariaLabelingProps = _useAriaLabelingProps(remainingProps);

  // If the disableFiltering value changes, the filterValue will need to be
  // reset
  useEffect(() => {
    if (
      slots.Filter?.props.disableFiltering === true &&
      (filterValue !== undefined || filterValue !== '')
    ) {
      setFilterValue('');
    }
    // We don't want to include filterValue as dependency because when the user types in the input and
    // disableFiltering is true, we don't want to clear the input
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [slots.Filter?.props.disableFiltering]);

  const filterConfig = {
    // when a textValue is on the option, the textValue is used;
    // otherwise we try and stringify whatever possible.
    stringify: (option) => {
      if (option.data.textValue) {
        return option.data.textValue;
      }
      return `${option.label} ${option.value}`;
    },
  };

  const handleChange = (
    option:
      | SelectV2SingleValue<_BaseOption<OptionValue>>
      | SelectV2MultiValue<_BaseOption<OptionValue>>,
  ) => {
    // Send native onChange event for any form control / onChange listeners
    requestAnimationFrame(() => {
      const nativeEvent = new Event('change', {
        bubbles: true,
        cancelable: true,
      });
      hiddenSelectRef?.current?.dispatchEvent(nativeEvent);
    });

    if (multiple === false) {
      setFilterValue(''); // clear the filter when an option is selected in single mode
    }

    // Early exit if the onChange prop is not defined, there is nothing that needs
    // to be done.
    if (!props.onChange) {
      return;
    }

    // In a single select scenario, it will only emit a single value of the selected option
    if (multiple === false) {
      // If the clicked option is the same as the selected one we can return early.
      if (option === value) {
        return;
      }
      if (option === null) {
        // Ensures that null is returned if no value is selected
        props.onChange?.(null as SelectV2OnChangeValue<OptionValue, Multiple>);
      } else {
        props.onChange?.(
          (option as SelectV2SingleValue<_BaseOption<OptionValue>>)
            ?.value as SelectV2OnChangeValue<OptionValue, Multiple>,
        );
      }
    }

    // In a multi select scenario, it will map the value of all selected options and report them
    // in the on change.
    if (multiple === true) {
      const selectedOptionValues = (
        option as SelectV2MultiValue<_BaseOption<OptionValue>>
      ).map((individualOption) => individualOption.value);
      props.onChange?.(
        selectedOptionValues as SelectV2OnChangeValue<OptionValue, Multiple>,
      );
    }
  };

  const filterRef = useRef<FormControlRef<HTMLDivElement>>(null);
  const clearSelectionRef = useRef<HTMLElement>(null);
  const containerRef = useRef(null);

  useImperativeHandle(
    forwardedRef,
    (): FormControlWithOverlayRef => ({
      element: containerRef.current,
      triggerRef: triggerRef,
      inputRef: hiddenSelectRef.current,
      focus: () => {
        triggerRef?.focus();
      },
      open: () => {
        // When opened programmatically the hidden select needs to be focused for the virtual focus
        hiddenTrigger?.focus();
        dispatch({
          type: SelectActions.OPEN,
        });
      },
      close: () =>
        dispatch({
          type: SelectActions.CLOSE,
        }),
    }),
    [triggerRef],
  );
  const [hasError] = _useFormControlState(controlState);
  return (
    <SelectMenuContext.Provider
      value={{
        state: menuOpen,
        dispatch,
      }}
    >
      <div
        ref={containerRef}
        data-testid={dataTestId}
        className={clsx(
          selectWrapperCSS({
            fullWidth:
              slots.Trigger?.props.width === 'full' ||
              slots.Trigger?.props.width === '100%',
          }),
          consumerClassName,
        )}
        style={consumerStyle}
      >
        <ReactSelect
          selectInputId={id}
          className={clsx({
            [validAndEnabledCSS]: !disabled && !hasError,
          })}
          unstyled
          options={options}
          components={components}
          // TODO: React select does an instance equality check on this one, so we need to figure out how
          // to keep that in sync over a controlled state.
          value={value}
          defaultValue={defaultValue}
          onChange={handleChange}
          hiddenSelectName={name}
          name={name}
          ariaLabelingProps={ariaLabelingProps}
          hiddenSelectRef={hiddenSelectRef}
          // This has to be set to false as we don't want the input directly in the select trigger
          // but handle this ourselves
          isSearchable={false}
          // Multi selection relevant props
          isMulti={props.multiple ?? false}
          hideSelectedOptions={false}
          closeMenuOnSelect={multiple === false}
          // This has to be set to false as we don't want the clear button directly in the select trigger
          // but handle this ourselves
          isClearable={false}
          isDisabled={disabled}
          isRequired={required}
          triggerWidth={slots.Trigger?.props.width}
          contentWidth={slots.Content?.props.width ?? 'trigger'}
          placeholderText={slots.Trigger?.props.placeholder}
          // DISCUSS: Figure out if `undefined` is better here or if we should use `null`
          displayValue={slots.DisplayValue ?? undefined}
          prefix={slots.Prefix ?? undefined}
          customTrigger={slots.CustomTrigger ?? undefined}
          // Trigger and Menu (Popper) ref connections
          triggerRef={triggerRef}
          setTriggerRef={setTriggerRef}
          // Reserving space for prefix icons
          optionsHavePrefix={optionsHavePrefix}
          menuIsOpen={menuOpen}
          // Handles Filtering in the current select
          filterOption={(option, inputValue) => {
            if (slots.Filter?.props.disableFiltering === true) {
              return true;
            }

            return createFilter(filterConfig)(option, inputValue);
          }}
          customFilter={slots.Filter ?? undefined}
          inputValue={filterValue}
          onInputChange={(newValue, actionmeta) => {
            if (actionmeta.action === 'input-change') {
              setFilterValue(newValue);
            }
          }}
          emptyState={slots.EmptyState ?? undefined}
          controlState={controlState}
          loading={slots.Content?.props.loading}
          clearable={clearable}
          allOptions={allOptions}
          tabSelectsValue={false}
          focusOnOption={focusOnOption}
          filterRef={filterRef}
          clearSelectionRef={clearSelectionRef}
          showSelectedOptionsFirst={
            slots.Content?.props.showSelectedOptionsFirst
          }
          componentProps={{
            trigger: {
              className: slots.Trigger?.props.className,
              style: slots.Trigger?.props.style,
              'data-testid': slots.Trigger?.props['data-testid'],
            },
            filter: {
              className: slots.Filter?.props.className,
              style: slots.Filter?.props.style,
              'data-testid': slots.Filter?.props['data-testid'],
            },
            content: {
              className: slots.Content?.props.className,
              style: slots.Content?.props.style,
              'data-testid': slots.Content?.props['data-testid'],
            },
            emptyState: {
              className: slots.EmptyState?.props.className,
              style: slots.EmptyState?.props.style,
              'data-testid': slots.EmptyState?.props['data-testid'],
            },
          }}
          onFocus={onFocus}
          onBlur={onBlur}
          onKeyDown={(event) => {
            if (!menuOpen) {
              if (event.key === 'Enter' || event.key === ' ') {
                dispatch({
                  type: SelectActions.SELECTFOCUS,
                });
              }
              return true;
            }

            // close the dropdown on Escape and focus the trigger
            if (event.key === 'Escape') {
              dispatch({
                type: SelectActions.SELECTFOCUS,
              });

              hiddenTrigger?.focus();
            }

            if (filterRef.current || clearSelectionRef.current) {
              // focus is on filter
              if (document.activeElement === filterRef.current?.inputRef) {
                // prevent option selection from being triggered (Space doesn't select when using a filter)
                // We also only want to remove selected values with Backspace when the focus is not on the filter input
                if (
                  event.key === 'Enter' ||
                  event.key === 'ArrowDown' ||
                  event.key === 'ArrowUp' ||
                  (event.key === 'Backspace' &&
                    filterRef.current.inputRef?.value === '')
                ) {
                  event.preventDefault();
                  event.stopPropagation();
                }

                // focus back on the trigger on tab if there is no clear selection element or shift tab is pressed
                if (event.key === 'Tab') {
                  if (!clearSelectionRef.current || event.shiftKey) {
                    event.preventDefault();
                    event.stopPropagation();
                    hiddenTrigger?.focus();
                    setFocusOnOption(true);
                  } else {
                    clearSelectionRef.current && setFocusOnOption(false); // prevent setting the focus on the option if there is a clear selection button when tabbing - the clear button should be the only element focused then
                  }
                }

                return false;
              }

              // focus is on the clear selection element
              if (document.activeElement === clearSelectionRef.current) {
                setFocusOnOption(false);
                if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
                  event.preventDefault();
                }

                // focus the trigger on tab (if it is not a shift tab press to focus back on the filter)
                if (
                  event.key === 'Tab' &&
                  !(event.shiftKey && filterRef.current)
                ) {
                  event.preventDefault();
                  event.stopPropagation();
                  hiddenTrigger?.focus();
                  setFocusOnOption(true);
                }
                return false;
              }

              try {
                // focus is on hidden input element
                if (
                  triggerRef?.querySelector(`#${document.activeElement?.id}`)
                ) {
                  if (event.key === 'Tab') {
                    event.preventDefault();
                    event.stopPropagation();
                    setFocusOnOption(false);

                    if (!event.shiftKey) {
                      // set focus on filter if available
                      if (filterRef.current) {
                        filterRef.current.inputRef?.focus();
                        return false;
                      }

                      // set focus on clearSelection if available
                      if (clearSelectionRef.current) {
                        clearSelectionRef.current.focus();
                        return false;
                      }
                    } else {
                      // set focus on clearSelection if available
                      if (clearSelectionRef.current) {
                        clearSelectionRef.current.focus();
                        return false;
                      }
                      // set focus on filter if available
                      if (filterRef.current) {
                        filterRef.current.inputRef?.focus();
                        return false;
                      }
                    }
                  }
                }
              } catch (error) {
                // eslint-disable-next-line no-console
                console.log(
                  'Invalid query selector on the SelectV2 trigger',
                  error,
                );
              }
              return false;
            }

            try {
              // close the dropdown when tab is pressed and no filter or clear selection is available
              if (
                triggerRef?.querySelector(`#${document.activeElement?.id}`) &&
                event.key === 'Tab'
              ) {
                dispatch({
                  type: SelectActions.SELECTFOCUS,
                });
              }
            } catch (error) {
              // eslint-disable-next-line no-console
              console.log(
                'Invalid query selector on the SelectV2 trigger',
                error,
              );
            }

            setFocusOnOption(true);
            return;
          }}
        />
      </div>
    </SelectMenuContext.Provider>
  );
}

_SelectV2.displayName = 'Select';

const SelectForwardRef = forwardRef(_SelectV2);

/**
 * The `SelectV2` component allows you to choose one or multiple
 * options from a collapsed dropdown with options.
 */
export const SelectV2 = Object.assign(SelectForwardRef, {
  Content: SelectV2Content,
  Option: SelectV2Option,
  Group: SelectV2Group,
  GroupLabel: SelectV2GroupLabel,
  Trigger: SelectV2Trigger,
  DisplayValue: SelectV2DisplayValue,
  Prefix: SelectV2Prefix,
  Suffix: SelectV2Suffix,
  CustomTrigger: SelectV2CustomTrigger,
  Filter: SelectV2Filter,
  EmptyState: SelectV2EmptyState,
});
